import{_ as a,o as i,c as d,a2 as o}from"./chunks/framework.BZO4qERu.js";const h=JSON.parse('{"title":"MediainfoNativeObject","description":"","frontmatter":{},"headers":[],"relativePath":"mediainfoNativeObjectType.md","filePath":"mediainfoNativeObjectType.md","lastUpdated":1780847608000}'),t={name:"mediainfoNativeObjectType.md"};function r(n,e,c,p,l,m){return i(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="mediainfonativeobject" tabindex="-1">MediainfoNativeObject</h1><p>MediainfoNativeObject 是 <code>mediainfo(path)</code> / <code>mediainfo.read(path)</code> 返回的媒体信息对象.</p><p>源码依据:</p><ul><li><code>app/src/main/java/org/autojs/autojs/runtime/api/augment/mediainfo/Mediainfo.kt</code></li><li><code>app/src/main/java/org/autojs/autojs/runtime/api/augment/mediainfo/MediainfoNativeObject.kt</code></li><li><code>app/src/main/java/org/mediainfo/android/MediaInfo.kt</code></li></ul><p>常见相关方法或属性:</p><ul><li><a href="./mediainfo#m-read">mediainfo.read</a>(path)</li></ul><hr><p style="font:bold 2em sans-serif;color:#FF7043;">MediainfoNativeObject</p><hr><p><code>MediainfoNativeObject</code> 构造时会读取一次 MediaInfo 输出文本, 并把文本解析为可访问的对象属性. 当前对象没有显式 <code>close()</code> 方法; 底层读取由 <code>scriptRuntime.mediaInfo</code> 完成.</p><h2 id="p-path" tabindex="-1">[p] path</h2><ul><li>{ <a href="./dataTypes#string">string</a> }</li></ul><p>运行时解析后的媒体文件路径.</p><h2 id="p-inform" tabindex="-1">[p] inform</h2><ul><li>{ <a href="./dataTypes#string">string</a> }</li></ul><p>MediaInfo 输出的原始文本. 动态属性解析也来自这段文本.</p><h2 id="m-general" tabindex="-1">[m] general</h2><h3 id="general-parameter" tabindex="-1">general(parameter?)</h3><ul><li><strong>[ parameter = <code>&quot;&quot;</code> ]</strong> { <a href="./dataTypes#string">string</a> }</li><li><ins><strong>returns</strong></ins> { <a href="./dataTypes#string">string</a> }</li></ul><p>读取 <code>GENERAL</code> 流第 <code>0</code> 个流的字段. <code>parameter</code> 为空时返回该流的默认信息.</p><h2 id="m-video" tabindex="-1">[m] video</h2><h3 id="video-parameter" tabindex="-1">video(parameter?)</h3><ul><li><strong>[ parameter = <code>&quot;&quot;</code> ]</strong> { <a href="./dataTypes#string">string</a> }</li><li><ins><strong>returns</strong></ins> { <a href="./dataTypes#string">string</a> }</li></ul><p>读取 <code>VIDEO</code> 流第 <code>0</code> 个流的字段.</p><h2 id="m-audio" tabindex="-1">[m] audio</h2><h3 id="audio-parameter" tabindex="-1">audio(parameter?)</h3><ul><li><strong>[ parameter = <code>&quot;&quot;</code> ]</strong> { <a href="./dataTypes#string">string</a> }</li><li><ins><strong>returns</strong></ins> { <a href="./dataTypes#string">string</a> }</li></ul><p>读取 <code>AUDIO</code> 流第 <code>0</code> 个流的字段.</p><h2 id="m-text" tabindex="-1">[m] text</h2><h3 id="text-parameter" tabindex="-1">text(parameter?)</h3><p>读取 <code>TEXT</code> 流第 <code>0</code> 个流的字段.</p><h2 id="m-other" tabindex="-1">[m] other</h2><h3 id="other-parameter" tabindex="-1">other(parameter?)</h3><p>读取 <code>OTHER</code> 流第 <code>0</code> 个流的字段.</p><h2 id="m-image" tabindex="-1">[m] image</h2><h3 id="image-parameter" tabindex="-1">image(parameter?)</h3><p>读取 <code>IMAGE</code> 流第 <code>0</code> 个流的字段.</p><h2 id="m-menu" tabindex="-1">[m] menu</h2><h3 id="menu-parameter" tabindex="-1">menu(parameter?)</h3><p>读取 <code>MENU</code> 流第 <code>0</code> 个流的字段.</p><h2 id="m-max" tabindex="-1">[m] max</h2><h3 id="max-parameter" tabindex="-1">max(parameter?)</h3><p>底层 <code>MediaInfo.StreamKind.MAX</code> 也会按枚举动态暴露为函数. 一般脚本不需要直接使用.</p><h2 id="动态分组属性" tabindex="-1">动态分组属性</h2><p><code>inform</code> 文本会按 section 解析为对象属性:</p><ul><li>section 标题会转为小写属性名, 例如 <code>General</code> -&gt; <code>info.general</code>.</li><li>字段名会转为 camelCase, 非字母数字分隔符会被移除, 例如 <code>Overall bit rate</code> -&gt; <code>overallBitRate</code>.</li><li>只解析包含冒号的行; 不含冒号的非空行会被视为新的 section.</li><li>解析后的字段值均为字符串.</li></ul><h2 id="异常与限制" tabindex="-1">异常与限制</h2><ul><li><code>path</code> 不能为 <code>null</code> / <code>undefined</code> / 空白字符串.</li><li>MediaInfo 原生库不可用时, 底层 <code>MediaInfo</code> 会抛出 <code>MediaInfo library is not available</code>.</li><li>各 stream 函数固定读取第 <code>0</code> 个流; 当前脚本包装层没有暴露 stream index 参数.</li><li>字段名称必须使用底层 MediaInfo 识别的参数名, 如 <code>Width</code> / <code>Format</code> / <code>Duration</code>.</li><li>动态属性名可能与 <code>general()</code> / <code>video()</code> 等动态函数同名. 依赖完整媒体字段时, 建议优先使用 <code>info.video(&#39;Width&#39;)</code> 这类函数形式.</li></ul>',48)])])}const f=a(t,[["render",r]]);export{h as __pageData,f as default};
